  r.put("featureManifest",fields("revision","CP4_FEATURE_1","graphHash",V51ChecksumEngine.sha256("pending"),"orderedFeatureIds",Collections.emptyList(),"featureTypes",Collections.emptyList(),"requiredHistory",0,"atomSpecHashes",Collections.emptyList(),"bindingHashes",Collections.emptyList(),"matrixSpecRefs",refs,"normalizerPolicy","TRAIN_ONLY_ZSCORE_V1","missingPolicyPerFeature",Collections.emptyList(),"inputDimension",4,"estimatedStateBytes",8*1024*1024));MutationGraphCP12.rebuildManifest(r,registry);return r;
