 static CandidateAstR952 ast(Map<String,Object> root){return CandidateAstR952.parse("AST3:"+StrictCanonicalJson.write(root));}
 static AtomSpecCP4 find(List<AtomSpecCP4> specs,String family,int order,double alpha){for(AtomSpecCP4 s:specs)if(s.family.equals(family)&&(!family.equals("MARKOV_SCORE")||s.mathSpec.order==order&&s.mathSpec.alpha==alpha))return s;throw new AssertionError("missing spec");}
 static AtomSpecCP4 byId(List<AtomSpecCP4> specs,String id){for(AtomSpecCP4 s:specs)if(s.atomId.equals(id))return s;throw new AssertionError(id);}
