   ok(changes==1);ok(changed.ast.graphSpec.manifest.requiredHistory==50+order);CandidateCompilerR952.compile(changed.ast,changed.ast.graphSpec.manifest,MutationGraphCP12.usedSpecs(changed.ast,registry));
   MutationGraphCP12.Proposal replay=MutationGraphCP12.propose(parent,null,"alpha"+order,"HYPERPARAM_MUTATION",registry,Collections.emptySet(),Collections.emptyList(),null,Long.MAX_VALUE);ok(changed.ast.canonical.equals(replay.ast.canonical));
