  ok(diverse.ast!=null);ok(diverse.ast.graphSpec.nodes.get(0).source.equals(old.atomId));AtomSpecCP4 replacement=byId(registry,diverse.ast.graphSpec.nodes.get(1).source);ok(!replacement.family.equals(old.family)&&replacement.outputType.equals(old.outputType));ok(diverse.ast.graphSpec.nodes.size()==2);ok(!MutationGraphCP12.semanticHash(diverse.ast).equals(MutationGraphCP12.semanticHash(parent)));CandidateCompilerR952.compile(diverse.ast,diverse.ast.graphSpec.manifest,MutationGraphCP12.usedSpecs(diverse.ast,registry));
  try(AtomWindowCP4 data=new AtomWindowCP4(new MemoryBudgetCP4(1L<<20))){for(int i=0;i<52;i++)data.append(i,0);double a=AtomEvaluatorCP4.evaluate(old.mathSpec,data,null,52).value,b=AtomEvaluatorCP4.evaluate(replacement.mathSpec,data,null,52).value;ok(Double.doubleToLongBits(a)!=Double.doubleToLongBits(b));}
  MutationGraphCP12.Proposal none=MutationGraphCP12.propose(parent,null,"no-diversity","DIVERSITY_INJECTION",Arrays.asList(old),Collections.emptySet(),Collections.emptyList(),null,Long.MAX_VALUE,Collections.emptyMap(),Arrays.asList("n1"));ok(none.ast==null&&none.attempt==32&&none.reason.endsWith("NO_TYPED_DIFFERENT_FAMILY_ATOM"));
